/* 2. CONSTANTS & CONFIGURATION                                               */
/* ========================================================================== */
/**
 * ============================================================================
 * WordleHelper - Constants & Configuration
 * ============================================================================
 * Defines grid dimensions, keyboard layout, color palettes for dark and light
 * modes, tile evaluation states, and animation timing parameters.
 */

window.WordleApp = window.WordleApp || {};

WordleApp.Constants = {
  /**
   * Grid dimensions for standard 5-letter Wordle puzzle
   */
  GRID: {
    ROWS: 6,
    COLS: 5,
  },

  /**
   * Physical QWERTY keyboard layout rows
   */
  KEYBOARD_ROWS: [
    ["Q", "W", "E", "R", "T", "Y", "U", "I", "O", "P"],
    ["A", "S", "D", "F", "G", "H", "J", "K", "L"],
    ["ENTER", "Z", "X", "C", "V", "B", "N", "M", "BACK"],
  ],

  /**
   * Dark theme color palette (RGB triplets)
   */
  DARK_COLORS: {
    bg: [18, 18, 19],
    tileBorderEmpty: [58, 58, 60],
    tileBorderActive: [86, 87, 88],
    tileBg: [18, 18, 19],
    keyBg: [129, 131, 132],
    keyText: [255, 255, 255],
    correct: [83, 141, 78],     // Green
    present: [181, 159, 59],    // Yellow
    absent: [58, 58, 60],       // Dark Gray
    text: [255, 255, 255],
    emptyTileText: [255, 255, 255],
    keyUnavailableBg: [36, 36, 38],
    keyUnavailableText: [90, 90, 92],
    keyEnterDisabledBg: [36, 36, 38],
    keyEnterDisabledText: [90, 90, 92],
    toastBg: [255, 255, 255],
    toastText: [18, 18, 19],
  },

  /**
   * Light theme color palette (RGB triplets)
   */
  LIGHT_COLORS: {
    bg: [255, 255, 255],
    tileBorderEmpty: [211, 214, 218],
    tileBorderActive: [135, 138, 140],
    tileBg: [255, 255, 255],
    keyBg: [211, 214, 218],
    keyText: [26, 26, 27],
    correct: [106, 170, 100],   // Green
    present: [201, 180, 88],    // Yellow
    absent: [120, 124, 126],    // Light Gray
    text: [255, 255, 255],
    emptyTileText: [26, 26, 27],
    keyUnavailableBg: [244, 244, 245],
    keyUnavailableText: [185, 187, 190],
    keyEnterDisabledBg: [244, 244, 245],
    keyEnterDisabledText: [185, 187, 190],
    toastBg: [26, 26, 27],
    toastText: [255, 255, 255],
  },

  /** Active colors pointer (updated dynamically by ThemeManager) */
  COLORS: null,

  /**
   * Tile evaluation states in order of user click cycling
   * Defaults to Green (correct) on key press, then cycles to Blank/Gray (absent) -> Yellow (present) -> Green (correct).
   * Note: No blank (empty) color state for filled grid cells.
   */
  TILE_STATES: ["correct", "absent", "present"],

  /**
   * Priority hierarchy for keyboard key coloring
   */
  STATE_PRIORITY: {
    empty: -1,
    absent: 0,
    present: 1,
    correct: 2,
  },

  /**
   * Animation durations and timing limits
   */
  ANIMATION: {
    FLIP_DURATION_MS: 300,
    TOAST_DURATION_FRAMES: 120,
  },
};

// Initialize active colors to DARK_COLORS by default
WordleApp.Constants.COLORS = { ...WordleApp.Constants.DARK_COLORS };



/* ========================================================================== */
/* 3. APPLICATION STATE MANAGEMENT                                            */
/* ========================================================================== */
/**
 * ============================================================================
 * WordleHelper - State Management
 * ============================================================================
 * Stores and manages the mutable application state: 6x5 board cells,
 * current cursor, live candidate word lists, letter availability, and toasts.
 */

window.WordleApp = window.WordleApp || {};

WordleApp.State = {
  /**
   * 2D array representing the 6x5 board:
   * Array<Array<{ letter: string, state: 'correct'|'present'|'absent'|'empty', flip: Object|null }>>
   */
  grid: [],

  /** Current active row index (0 to ROWS - 1) */
  currentRow: 0,

  /** Current active column index (0 to COLS) */
  currentCol: 0,

  /** Indicates if the game has ended (either solved or ran out of attempts) */
  gameOver: false,

  /** Text message for on-canvas toast notification */
  message: "",

  /** Remaining frames for displaying the toast (~60 fps) */
  messageTimer: 0,

  /** List of words valid against all confirmed rows */
  remainingWords: [],

  /** List of words dynamically valid against current typing & feedback */
  liveWords: [],

  /** Set of uppercase letters that can appear next in liveWords */
  possibleLetters: new Set(),

  /** Map tracking the highest revealed state for each keyboard letter (letter -> state) */
  keyStates: {},

  /** Click bounding boxes for on-screen keyboard buttons [{ key, x, y, w, h }, ...] */
  keyButtons: [],

  /**
   * Initializes or resets the board and dictionary state.
   * @param {string[]} initialWordList - Master dictionary of 5-letter words.
   */
  init(initialWordList = []) {
    const { ROWS, COLS } = WordleApp.Constants.GRID;

    this.grid = [];
    for (let r = 0; r < ROWS; r++) {
      this.grid[r] = [];
      for (let c = 0; c < COLS; c++) {
        this.grid[r][c] = {
          letter: "",
          state: "empty",
          flip: null,
        };
      }
    }

    this.currentRow = 0;
    this.currentCol = 0;
    this.gameOver = false;
    this.message = "";
    this.messageTimer = 0;
    this.keyStates = {};
    this.keyButtons = [];

    const masterList = Array.isArray(initialWordList) && initialWordList.length > 0
      ? initialWordList
      : (typeof WORD_LIST !== "undefined" ? WORD_LIST : []);

    this.remainingWords = [...masterList];
    this.liveWords = [...this.remainingWords];
    this.possibleLetters = new Set();
  },

  /**
   * Resets everything back to fresh new game state.
   */
  reset() {
    const masterList = typeof WORD_LIST !== "undefined" ? WORD_LIST : [];
    this.init(masterList);
    if (WordleApp.Solver) {
      WordleApp.Solver.refreshLiveCandidates();
    }
    this.showToast("Reset complete", 90);
  },

  /**
   * Displays an on-screen toast message for a specified duration in frames.
   * @param {string} msg - Message text to display.
   * @param {number} [durationFrames=120] - Number of frames to keep toast visible.
   */
  showToast(msg, durationFrames = WordleApp.Constants.ANIMATION.TOAST_DURATION_FRAMES) {
    this.message = msg;
    this.messageTimer = durationFrames;
  },

  /**
   * Decrements the toast timer by 1 frame if active.
   */
  tickToast() {
    if (this.messageTimer > 0) {
      this.messageTimer--;
    }
  },
};



/* ========================================================================== */
/* 4. CANDIDATE WORDS SORTING ENGINE                                          */
/* ========================================================================== */
/**
 * ============================================================================
 * WordleHelper - Candidate Words Sorting Engine
 * ============================================================================
 * Supports two distinct candidate sorting strategies:
 * 1. 'word with high letters frequency' (default):
 *    Calculates dynamic letter frequency across the remaining candidate words
 *    and scores each word by the sum of frequencies of its unique letters.
 * 2. 'most friquent word used':
 *    Sorts candidate words according to real-world English usage frequency,
 *    prioritizing common, everyday vocabulary over obscure dictionary words.
 */

window.WordleApp = window.WordleApp || {};

WordleApp.WordSorter = {
  // Sort order identifier constants matching user specifications
  SORT_HIGH_LETTERS_FREQ: "word with high letters frequency",
  SORT_MOST_FREQUENT_USED: "most friquent word used",

  // Baseline English letter frequencies for 5-letter words (normalized weights)
  ENGLISH_LETTER_WEIGHTS: {
    E: 12.3, A: 8.5, R: 7.6, O: 7.2, T: 7.0, I: 6.7, L: 5.8, S: 5.7, N: 5.7,
    C: 4.8, U: 4.6, Y: 4.2, D: 4.0, H: 3.9, P: 3.7, M: 3.2, G: 3.1, B: 2.8,
    F: 2.3, K: 2.1, W: 1.7, V: 1.5, Z: 0.8, X: 0.6, Q: 0.3, J: 0.3,
  },

  /**
   * Sorts candidate words based on the requested sort order.
   *
   * @param {string[]} words - Array of candidate words.
   * @param {string} [sortOrder] - Sort strategy identifier.
   * @returns {string[]} Newly sorted array of candidate words.
   */
  sortCandidates(words, sortOrder = this.SORT_HIGH_LETTERS_FREQ) {
    if (!words || words.length <= 1) {
      return words ? [...words] : [];
    }

    if (sortOrder === this.SORT_MOST_FREQUENT_USED) {
      return this.sortByWordFrequency(words);
    }

    // Default: 'word with high letters frequency'
    return this.sortByLetterFrequency(words);
  },

  /**
   * Strategy 1: 'word with high letters frequency'
   * Evaluates each word by the frequency of its unique letters within the current
   * candidate set, plus baseline 5-letter English letter weights.
   *
   * @param {string[]} words
   * @returns {string[]}
   */
  sortByLetterFrequency(words) {
    // 1. Calculate how many words in the current candidate pool contain each letter
    const letterCounts = {};
    for (let i = 0; i < words.length; i++) {
      const word = words[i];
      const seen = new Set();
      for (let j = 0; j < word.length; j++) {
        const char = word[j];
        if (!seen.has(char)) {
          seen.add(char);
          letterCounts[char] = (letterCounts[char] || 0) + 1;
        }
      }
    }

    // 2. Score each word based on unique letters' pool counts + English weights
    const scores = new Map();
    for (let i = 0; i < words.length; i++) {
      const word = words[i];
      let score = 0;
      const seen = new Set();
      for (let j = 0; j < word.length; j++) {
        const char = word[j];
        if (!seen.has(char)) {
          seen.add(char);
          score += (letterCounts[char] || 0) * 10 + (this.ENGLISH_LETTER_WEIGHTS[char] || 0);
        }
      }
      scores.set(word, score);
    }

    // 3. Sort descending by score, tie-breaking by word frequency rank then alphabetical
    const sorted = [...words].sort((a, b) => {
      const diff = scores.get(b) - scores.get(a);
      if (Math.abs(diff) > 0.001) {
        return diff;
      }
      if (WordleApp.WordFrequency) {
        const rankDiff =
          WordleApp.WordFrequency.getFrequencyRank(a) -
          WordleApp.WordFrequency.getFrequencyRank(b);
        if (rankDiff !== 0) return rankDiff;
      }
      return a.localeCompare(b);
    });

    return sorted;
  },

  /**
   * Strategy 2: 'most friquent word used'
   * Sorts candidate words by their English usage frequency rank (rank 1 = most common).
   *
   * @param {string[]} words
   * @returns {string[]}
   */
  sortByWordFrequency(words) {
    if (!WordleApp.WordFrequency) {
      return [...words];
    }

    const letterWeights = this.ENGLISH_LETTER_WEIGHTS;
    const getLetterScore = (word) => {
      let s = 0;
      const seen = new Set();
      for (let i = 0; i < word.length; i++) {
        const c = word[i];
        if (!seen.has(c)) {
          seen.add(c);
          s += (letterWeights[c] || 0);
        }
      }
      return s;
    };

    const sorted = [...words].sort((a, b) => {
      const rankA = WordleApp.WordFrequency.getFrequencyRank(a);
      const rankB = WordleApp.WordFrequency.getFrequencyRank(b);

      if (rankA !== rankB) {
        return rankA - rankB; // lower rank number = more frequent in English
      }

      // If tied (e.g. both are obscure dictionary words), rank by letter frequency score
      const scoreA = getLetterScore(a);
      const scoreB = getLetterScore(b);
      if (scoreA !== scoreB) {
        return scoreB - scoreA;
      }

      return a.localeCompare(b);
    });

    return sorted;
  },

  /**
   * Toggles/cycles between the two supported sort orders.
   *
   * @param {string} currentOrder
   * @returns {string} Next sort order.
   */
  cycleOrder(currentOrder) {
    if (currentOrder === this.SORT_HIGH_LETTERS_FREQ) {
      return this.SORT_MOST_FREQUENT_USED;
    }
    return this.SORT_HIGH_LETTERS_FREQ;
  },

  /**
   * Returns a concise button label for the active sort order.
   *
   * @param {string} order
   * @returns {string} Short display label.
   */
  getButtonLabel(order) {
    if (order === this.SORT_MOST_FREQUENT_USED) {
      return "Most Frequent Used";
    }
    return "High Letter Freq";
  },

  /**
   * Returns an informative description for the active sort banner.
   *
   * @param {string} order
   * @returns {string} Detailed description banner text.
   */
  getDescription(order) {
    if (order === this.SORT_MOST_FREQUENT_USED) {
      return "Order: most friquent word used";
    }
    return "Order: word with high letters frequency";
  },
};



/* ========================================================================== */
/* 5. WORDLE CONSTRAINT & SOLVER ENGINE                                       */
/* ========================================================================== */
/**
 * ============================================================================
 * WordleHelper - Constraint & Candidate Evaluation Engine
 * ============================================================================
 * Evaluates board feedback against 5-letter candidate words using:
 * 1. Exact two-pass Wordle matching for complete rows.
 * 2. Positional and frequency constraints for partial feedback.
 * 3. Dynamic possible letters calculation to guide typing without Enter key.
 */

window.WordleApp = window.WordleApp || {};

WordleApp.Solver = {
  /**
   * Evaluates a guess against a target word candidate following standard Wordle rules.
   *
   * @param {string} guess - The 5-letter guessed word.
   * @param {string} candidate - The target 5-letter candidate word.
   * @returns {string[]} Array of states ('correct'|'present'|'absent') for each column.
   */
  evaluateGuess(guess, candidate) {
    const { COLS } = WordleApp.Constants.GRID;
    const result = Array(COLS).fill("absent");
    const remaining = candidate.split("");

    // Pass 1: Exact positional matches
    for (let i = 0; i < COLS; i++) {
      if (guess[i] === candidate[i]) {
        result[i] = "correct";
        remaining[i] = null;
      }
    }

    // Pass 2: Present in wrong position
    for (let i = 0; i < COLS; i++) {
      if (result[i] === "correct") continue;
      const targetIndex = remaining.indexOf(guess[i]);
      if (targetIndex !== -1) {
        result[i] = "present";
        remaining[targetIndex] = null;
      }
    }

    return result;
  },

  /**
   * Updates state.possibleLetters to restrict keyboard input:
   * 1. While typing in current row (col < COLS): allows letters that can be next.
   * 2. When row is full (col === COLS): allows letters that can start the next row
   *    as long as more than one candidate remains (liveWords.length > 1).
   * 3. When only 1 candidate remains, further typing is halted.
   */
  updatePossibleLetters() {
    const state = WordleApp.State;
    const { ROWS, COLS } = WordleApp.Constants.GRID;
    state.possibleLetters = new Set();

    if (state.gameOver || state.currentRow >= ROWS) {
      return;
    }

    if (state.currentCol < COLS) {
      // Only allow letters that can appear at the current column for remaining candidates
      const col = state.currentCol;
      for (let i = 0; i < state.liveWords.length; i++) {
        const word = state.liveWords[i];
        if (word && word.length > col) {
          state.possibleLetters.add(word[col]);
        }
      }
    } else if (state.currentCol === COLS) {
      // Current row is full. Allow starting letters for the next row if more than 1 candidate remains
      if (state.currentRow < ROWS - 1 && state.liveWords.length > 1) {
        for (let i = 0; i < state.liveWords.length; i++) {
          const word = state.liveWords[i];
          if (word && word.length > 0) {
            state.possibleLetters.add(word[0]);
          }
        }
      }
    }
  },

  /**
   * Filters the remaining candidate words based on confirmed rows and active row feedback.
   */
  refreshLiveCandidates() {
    const state = WordleApp.State;
    const { ROWS, COLS } = WordleApp.Constants.GRID;

    if (state.currentRow >= ROWS) {
      state.liveWords = [...state.remainingWords];
    } else {
      const row = state.grid[state.currentRow];
      const typedCells = row
        .map((cell, index) => ({ ...cell, index }))
        .filter((cell) => cell.letter);

      const completeFeedback =
        row.length === COLS &&
        row.every(
          (cell) => cell.letter && ["correct", "present", "absent"].includes(cell.state)
        );
      const guess = row.map((cell) => cell.letter).join("");
      const coloredCells = typedCells.filter((cell) => cell.state !== "empty");

      if (completeFeedback) {
        // Complete row feedback provided
        state.liveWords = state.remainingWords.filter((candidate) =>
          this.evaluateGuess(guess, candidate).every(
            (cellState, index) => cellState === row[index].state
          )
        );
      } else if (coloredCells.length > 0) {
        // Partial feedback mode
        const minimumCounts = {};
        const maximumCounts = {};
        const hasAbsent = new Set();

        for (let i = 0; i < coloredCells.length; i++) {
          const cell = coloredCells[i];
          if (cell.state !== "absent") {
            minimumCounts[cell.letter] = (minimumCounts[cell.letter] || 0) + 1;
          } else {
            hasAbsent.add(cell.letter);
          }
        }

        for (const letter of hasAbsent) {
          maximumCounts[letter] = minimumCounts[letter] || 0;
        }

        state.liveWords = state.remainingWords.filter((candidate) => {
          // Positional constraints
          for (let i = 0; i < coloredCells.length; i++) {
            const cell = coloredCells[i];
            if (cell.state === "correct") {
              if (candidate[cell.index] !== cell.letter) return false;
            } else if (cell.state === "present" || cell.state === "absent") {
              if (candidate[cell.index] === cell.letter) return false;
            }
          }

          // Count constraints
          const counts = {};
          for (let i = 0; i < candidate.length; i++) {
            const letter = candidate[i];
            counts[letter] = (counts[letter] || 0) + 1;
          }

          for (const [letter, count] of Object.entries(minimumCounts)) {
            if ((counts[letter] || 0) < count) return false;
          }

          for (const [letter, count] of Object.entries(maximumCounts)) {
            if ((counts[letter] || 0) > count) return false;
          }

          return true;
        });
      } else {
        // All uncolored tiles: filter by prefix if any letters entered
        const prefix = row
          .slice(0, state.currentCol)
          .map((cell) => cell.letter)
          .join("");

        if (prefix.length > 0) {
          state.liveWords = state.remainingWords.filter((candidate) =>
            candidate.startsWith(prefix)
          );
        } else {
          state.liveWords = [...state.remainingWords];
        }
      }
    }

    if (state.currentCol < COLS || state.liveWords.length > 1) {
      state.gameOver = false;
    }

    this.updatePossibleLetters();

    if (WordleApp.DOMManager) {
      WordleApp.DOMManager.updateCandidateList(state.liveWords);
      WordleApp.DOMManager.updateHeaderBadge(state.liveWords.length);
    }
  },

  /**
   * Rebuilds candidate words against all previously locked rows.
   */
  rebuildRemainingWords() {
    const state = WordleApp.State;
    const wordList = typeof WORD_LIST !== "undefined" ? WORD_LIST : [];

    state.remainingWords = wordList.filter((candidate) => {
      for (let rowIndex = 0; rowIndex < state.currentRow; rowIndex++) {
        const row = state.grid[rowIndex];
        if (!WordleApp.InputHandler.isRowComplete(row)) return false;
        const guess = row.map((cell) => cell.letter).join("");
        const feedback = row.map((cell) => cell.state);
        if (!this.evaluateGuess(guess, candidate).every((s, i) => s === feedback[i])) {
          return false;
        }
      }
      return true;
    });

    // Reconstruct key state colors based on confirmed rows
    state.keyStates = {};
    const priority = WordleApp.Constants.STATE_PRIORITY;

    for (let rowIndex = 0; rowIndex < state.currentRow; rowIndex++) {
      for (let c = 0; c < state.grid[rowIndex].length; c++) {
        const cell = state.grid[rowIndex][c];
        if (cell.state !== "empty") {
          if (
            state.keyStates[cell.letter] === undefined ||
            priority[cell.state] > priority[state.keyStates[cell.letter]]
          ) {
            state.keyStates[cell.letter] = cell.state;
          }
        }
      }
    }

    this.refreshLiveCandidates();
  },
};



/* ========================================================================== */
/* 6. RESPONSIVE CANVAS LAYOUT CALCULATOR                                     */
/* ========================================================================== */
/**
 * ============================================================================
 * WordleHelper - Responsive Layout Calculator
 * ============================================================================
 * Computes fluid dimensions, margins, and coordinate placement for the 6x5 board
 * grid and on-screen keyboard based on dynamic canvas dimensions.
 */

window.WordleApp = window.WordleApp || {};

WordleApp.Layout = {
  /**
   * Calculates responsive layout parameters for the canvas viewport.
   *
   * @param {number} width - Canvas width in pixels.
   * @param {number} height - Canvas height in pixels.
   * @returns {Object} Computed layout properties.
   */
  getLayout(width, height) {
    const { ROWS, COLS } = WordleApp.Constants.GRID;
    const { KEYBOARD_ROWS } = WordleApp.Constants;

    // Responsive keyboard metrics
    const keyGap = Math.max(4, Math.min(6, width * 0.012));
    const baseKeyW = Math.min(44, (width - 16 - 9 * keyGap) / 10);
    const keyH = Math.min(58, Math.max(38, baseKeyW * 1.35));
    const keyboardHeight = KEYBOARD_ROWS.length * keyH + (KEYBOARD_ROWS.length - 1) * keyGap;
    const keyboardStartY = Math.max(0, height - keyboardHeight - 12);

    // Responsive tile metrics
    const tileGap = Math.max(4, Math.min(7, width * 0.015));
    const maxTileW = (width - 32 - (COLS - 1) * tileGap) / COLS;
    const availableGridH = Math.max(100, keyboardStartY - 24);
    const maxTileH = (availableGridH - (ROWS - 1) * tileGap) / ROWS;

    const tileSize = Math.min(58, Math.max(30, Math.min(maxTileW, maxTileH)));
    const totalGridHeight = ROWS * tileSize + (ROWS - 1) * tileGap;
    const gridStartY = Math.max(10, (keyboardStartY - totalGridHeight) / 2);

    const scale = Math.min(1.2, Math.max(0.65, tileSize / 52));

    return {
      scale,
      tileGap,
      tileSize,
      gridStartY,
      keyGap,
      baseKeyW,
      keyH,
      keyboardStartY,
    };
  },
};



/* ========================================================================== */
/* 7. THEME MANAGER (SYSTEM / DARK / LIGHT)                                   */
/* ========================================================================== */
/**
 * ============================================================================
 * WordleHelper - Theme Manager
 * ============================================================================
 * Manages 3-state theme cycling: System (default) -> Dark -> Light -> System.
 * Synchronizes HTML data-theme attributes, CSS custom properties, and p5 canvas
 * rendering colors. Persists user preference across page reloads via localStorage.
 */

window.WordleApp = window.WordleApp || {};

WordleApp.ThemeManager = {
  STORAGE_KEY: "wordlehelper_theme",
  MODES: ["system", "dark", "light"],
  currentMode: "system",

  themeToggleBtn: null,
  themeIconElem: null,
  themeLabelElem: null,
  mediaQuery: null,

  /**
   * Initializes theme preferences and DOM event listeners.
   */
  init() {
    this.themeToggleBtn = document.getElementById("theme-toggle-btn");
    this.themeIconElem = document.getElementById("theme-icon");
    this.themeLabelElem = document.getElementById("theme-label");
    this.mediaQuery = window.matchMedia("(prefers-color-scheme: dark)");

    // Retrieve saved theme preference (default to 'system')
    const saved = localStorage.getItem(this.STORAGE_KEY);
    if (saved && this.MODES.includes(saved)) {
      this.currentMode = saved;
    } else {
      this.currentMode = "system";
    }

    // Apply active theme immediately
    this.applyTheme();

    // Attach click listener to app bar toggle button
    if (this.themeToggleBtn) {
      this.themeToggleBtn.addEventListener("click", () => {
        this.cycleTheme();
      });
    }

    // React to operating system color scheme changes when in 'system' mode
    if (this.mediaQuery && this.mediaQuery.addEventListener) {
      this.mediaQuery.addEventListener("change", () => {
        if (this.currentMode === "system") {
          this.applyTheme();
        }
      });
    }
  },

  /**
   * Resolves active effective theme ('dark' or 'light').
   * @returns {'dark'|'light'}
   */
  getEffectiveTheme() {
    if (this.currentMode === "system") {
      return this.mediaQuery && this.mediaQuery.matches ? "dark" : "light";
    }
    return this.currentMode;
  },

  /**
   * Cycles mode in the order: system -> dark -> light -> system.
   */
  cycleTheme() {
    const nextIdx = (this.MODES.indexOf(this.currentMode) + 1) % this.MODES.length;
    this.currentMode = this.MODES[nextIdx];

    try {
      localStorage.setItem(this.STORAGE_KEY, this.currentMode);
    } catch (e) {
      // Storage might be disabled or restricted in private browsing
    }

    this.applyTheme();
  },

  /**
   * Updates DOM attributes, canvas colors, and button indicator icons.
   */
  applyTheme() {
    const effective = this.getEffectiveTheme();

    // Update document element data-theme attribute for CSS tokens
    document.documentElement.setAttribute("data-theme", effective);

    // Sync p5.js canvas colors
    const targetColors =
      effective === "light"
        ? WordleApp.Constants.LIGHT_COLORS
        : WordleApp.Constants.DARK_COLORS;

    Object.assign(WordleApp.Constants.COLORS, targetColors);

    // Update App Bar Button visual state
    if (this.themeIconElem && this.themeLabelElem) {
      if (this.currentMode === "system") {
        this.themeIconElem.textContent = "💻";
        this.themeLabelElem.textContent = "System";
      } else if (this.currentMode === "dark") {
        this.themeIconElem.textContent = "🌙";
        this.themeLabelElem.textContent = "Dark";
      } else {
        this.themeIconElem.textContent = "☀️";
        this.themeLabelElem.textContent = "Light";
      }
    }

    if (this.themeToggleBtn) {
      const readable =
        this.currentMode === "system"
          ? `System (${effective})`
          : this.currentMode.charAt(0).toUpperCase() + this.currentMode.slice(1);
      this.themeToggleBtn.setAttribute(
        "aria-label",
        `Theme: ${readable}. Click to cycle: System, Dark, Light.`
      );
      this.themeToggleBtn.setAttribute(
        "title",
        `Theme: ${readable} (click to cycle)`
      );
    }
  },
};

// Immediate early check for theme to prevent flicker before p5 canvas setup
try {
  const savedMode = localStorage.getItem("wordlehelper_theme");
  const modeVal = savedMode && ["system", "dark", "light"].includes(savedMode) ? savedMode : "system";
  const effectiveVal = modeVal === "system"
    ? (window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light")
    : modeVal;
  document.documentElement.setAttribute("data-theme", effectiveVal);
} catch (e) {}



/* ========================================================================== */
/* 8. DOM & FULL-SCREEN NAVIGATION MANAGER                                    */
/* ========================================================================== */
/**
 * ============================================================================
 * WordleHelper - DOM & Navigation Manager
 * ============================================================================
 * Manages full-screen navigation between Game Board View and Word List Page:
 * 1. Tapping the top-right remaining words badge navigates to the List Page.
 * 2. In List Page:
 *    - Top Left: Back button to return to board.
 *    - Top Center: Dynamic remaining words count.
 *    - Top Right: 2 sort order cycle button:
 *      * Default: 'word with high letters frequency'
 *      * Second: 'most friquent word used'
 * 3. Selecting any candidate word populates the board and returns to the game.
 * 4. Batched progressive rendering for smooth, high-fps list scrolling.
 */

window.WordleApp = window.WordleApp || {};

WordleApp.DOMManager = {
  // Navigation & Page references
  gameElement: null,
  appBarElement: null,
  listPageElement: null,
  listBackBtn: null,
  listScrollContainer: null,

  // Counters
  headerBadgeButton: null,
  headerWordCountElement: null,
  listWordCountElement: null,
  listCountLabelElement: null,

  // Sort order controls
  sortCycleBtn: null,
  sortBtnLabel: null,
  sortBannerText: null,
  sortBannerIcon: null,

  // Word grid container & buttons
  candidateListElement: null,
  appTitleButton: null,

  // State
  currentSortOrder: "word with high letters frequency",
  rawCandidates: [],
  sortedCandidates: [],
  renderedCount: 0,
  BATCH_SIZE: 250,
  isListPageVisible: false,

  /**
   * Initializes DOM references and binds event listeners.
   */
  init() {
    // 1. Cache Main App Elements
    this.gameElement = document.getElementById("game");
    this.appBarElement = document.getElementById("app-bar");
    this.appTitleButton = document.getElementById("app-title-btn");
    this.headerBadgeButton = document.getElementById("header-candidate-badge");
    this.headerWordCountElement = document.getElementById("header-word-count");

    // 2. Cache List Page Elements
    this.listPageElement = document.getElementById("list-page");
    this.listBackBtn = document.getElementById("list-back-btn");
    this.listScrollContainer = document.getElementById("list-scroll-container");
    this.candidateListElement = document.getElementById("candidate-list");

    this.listWordCountElement = document.getElementById("list-word-count");
    this.listCountLabelElement = document.getElementById("list-count-label");

    this.sortCycleBtn = document.getElementById("sort-order-cycle-btn");
    this.sortBtnLabel = document.getElementById("sort-order-btn-label");
    this.sortBannerText = document.getElementById("sort-banner-text");
    this.sortBannerIcon = document.getElementById("sort-banner-icon");

    // Default sort order is 'word with high letters frequency'
    if (WordleApp.WordSorter) {
      this.currentSortOrder = WordleApp.WordSorter.SORT_HIGH_LETTERS_FREQ;
    }

    // 3. Bind Title Reset Button
    if (this.appTitleButton) {
      this.appTitleButton.addEventListener("click", () => {
        if (WordleApp.State) {
          WordleApp.State.reset();
        }
      });
    }

    // 4. Bind Header Badge: Navigate to List Page on tap
    if (this.headerBadgeButton) {
      this.headerBadgeButton.addEventListener("click", () => {
        this.showListPage();
      });
    }

    // 5. Bind List Page Back Button: Return to Game Board
    if (this.listBackBtn) {
      this.listBackBtn.addEventListener("click", () => {
        this.hideListPage();
      });
    }

    // 6. Bind Sort Order Cycle Button
    if (this.sortCycleBtn) {
      this.sortCycleBtn.addEventListener("click", () => {
        this.cycleSortOrder();
      });
    }

    // 7. Delegated click handler on Candidate Word tiles
    if (this.candidateListElement) {
      this.candidateListElement.addEventListener("click", (event) => {
        const item = event.target.closest(".candidate-word");
        if (item && WordleApp.InputHandler) {
          const word = item.textContent.trim();
          WordleApp.InputHandler.selectCandidate(word);
          this.hideListPage();
        }
      });
    }

    // 8. Batched progressive scroll for large candidate lists
    if (this.listScrollContainer) {
      this.listScrollContainer.addEventListener("scroll", () => {
        const { scrollTop, scrollHeight, clientHeight } = this.listScrollContainer;
        if (scrollHeight - (scrollTop + clientHeight) < 250) {
          this.renderNextBatch();
        }
      });
    }

    // 9. Keyboard Escape handler to exit List Page
    window.addEventListener("keydown", (e) => {
      if (this.isListPageVisible && (e.key === "Escape" || e.keyCode === 27)) {
        this.hideListPage();
      }
    });

    this.updateSortUI();
  },

  /**
   * Opens the full List Page view and renders sorted candidates.
   */
  showListPage() {
    if (!this.listPageElement) return;

    this.isListPageVisible = true;
    this.listPageElement.hidden = false;
    this.listPageElement.classList.add("active");
    document.body.classList.add("list-open");

    this.updateSortUI();
    this.renderSortedCandidates(true);
  },

  /**
   * Closes the List Page view and restores the game board.
   */
  hideListPage() {
    if (!this.listPageElement) return;

    this.isListPageVisible = false;
    this.listPageElement.hidden = true;
    this.listPageElement.classList.remove("active");
    document.body.classList.remove("list-open");
  },

  /**
   * Checks whether the List Page is currently visible.
   * @returns {boolean}
   */
  isListPageOpen() {
    return Boolean(this.isListPageVisible);
  },

  /**
   * Cycles between 'word with high letters frequency' and 'most friquent word used'.
   */
  cycleSortOrder() {
    if (WordleApp.WordSorter) {
      this.currentSortOrder = WordleApp.WordSorter.cycleOrder(this.currentSortOrder);
    } else {
      this.currentSortOrder =
        this.currentSortOrder === "word with high letters frequency"
          ? "most friquent word used"
          : "word with high letters frequency";
    }

    this.updateSortUI();
    this.renderSortedCandidates(true);
  },

  /**
   * Synchronizes sort button and banner UI with active sort order.
   */
  updateSortUI() {
    const isMostFrequent = this.currentSortOrder === "most friquent word used";

    if (this.sortBtnLabel) {
      this.sortBtnLabel.textContent = isMostFrequent
        ? "Most Frequent Used"
        : "High Letter Freq";
    }

    if (this.sortCycleBtn) {
      this.sortCycleBtn.setAttribute(
        "title",
        `Current: ${this.currentSortOrder}. Click to switch order.`
      );
      this.sortCycleBtn.setAttribute(
        "aria-label",
        `Current sort order: ${this.currentSortOrder}. Click to cycle.`
      );
    }

    if (this.sortBannerText) {
      this.sortBannerText.textContent = isMostFrequent
        ? "Order: 'most friquent word used'"
        : "Order: 'word with high letters frequency'";
    }

    if (this.sortBannerIcon) {
      this.sortBannerIcon.textContent = isMostFrequent ? "📈" : "🔤";
    }
  },

  /**
   * Updates candidate list data and badges from solver.
   *
   * @param {string[]} words - Array of viable candidate words.
   */
  updateCandidateList(words) {
    this.rawCandidates = Array.isArray(words) ? words : [];
    const count = this.rawCandidates.length;

    // 1. Update header candidate words badge
    this.updateHeaderBadge(count);

    // 2. Update list page top center count badge
    if (this.listWordCountElement) {
      this.listWordCountElement.textContent = count.toLocaleString();
    }
    if (this.listCountLabelElement) {
      this.listCountLabelElement.textContent = count === 1 ? "word" : "words";
    }

    // 3. If list page is actively open, re-render
    if (this.isListPageVisible) {
      this.renderSortedCandidates(false);
    }
  },

  /**
   * Sorts the raw candidates array and renders the first batch into the DOM.
   *
   * @param {boolean} [resetScroll=true] - Whether to scroll to top.
   */
  renderSortedCandidates(resetScroll = true) {
    if (!this.candidateListElement) return;

    if (WordleApp.WordSorter) {
      this.sortedCandidates = WordleApp.WordSorter.sortCandidates(
        this.rawCandidates,
        this.currentSortOrder
      );
    } else {
      this.sortedCandidates = [...this.rawCandidates];
    }

    this.candidateListElement.innerHTML = "";
    this.renderedCount = 0;

    if (resetScroll && this.listScrollContainer) {
      this.listScrollContainer.scrollTop = 0;
    }

    if (this.sortedCandidates.length === 0) {
      const emptyNote = document.createElement("div");
      emptyNote.className = "candidate-empty-message";
      emptyNote.textContent = "No matching words found. Check tile colors.";
      this.candidateListElement.appendChild(emptyNote);
      return;
    }

    this.renderNextBatch();
  },

  /**
   * Appends the next batch of candidate tiles to the DOM.
   */
  renderNextBatch() {
    if (!this.candidateListElement) return;
    if (this.renderedCount >= this.sortedCandidates.length) return;

    const total = this.sortedCandidates.length;
    const end = Math.min(this.renderedCount + this.BATCH_SIZE, total);
    const fragment = document.createDocumentFragment();

    for (let i = this.renderedCount; i < end; i++) {
      const word = this.sortedCandidates[i];
      const item = document.createElement("button");
      item.type = "button";
      item.className = "candidate-word";
      item.setAttribute("role", "listitem");
      item.setAttribute("aria-label", `Select word ${word}`);
      item.textContent = word;
      fragment.appendChild(item);
    }

    this.candidateListElement.appendChild(fragment);
    this.renderedCount = end;

    // Show counter info at bottom if large dictionary
    let statusNote = this.candidateListElement.querySelector(".candidate-more-note");
    if (this.renderedCount < total) {
      if (!statusNote) {
        statusNote = document.createElement("div");
        statusNote.className = "candidate-more-note";
        this.candidateListElement.appendChild(statusNote);
      }
      statusNote.textContent = `Showing ${this.renderedCount} of ${total.toLocaleString()} words (scroll down for more)`;
      // Ensure statusNote is at the end
      this.candidateListElement.appendChild(statusNote);
    } else if (statusNote) {
      statusNote.remove();
    }
  },

  /**
   * Updates the live counter on the top app bar badge.
   *
   * @param {number} count - Remaining candidate word count.
   */
  updateHeaderBadge(count) {
    if (this.headerWordCountElement) {
      this.headerWordCountElement.textContent = count.toLocaleString();
    }
    if (this.headerBadgeButton) {
      this.headerBadgeButton.setAttribute(
        "title",
        `Tap to view remaining words list (${count.toLocaleString()} left)`
      );
      this.headerBadgeButton.setAttribute(
        "aria-label",
        `View remaining words list, ${count.toLocaleString()} words left`
      );
    }
  },
};



/* ========================================================================== */
/* 9. P5.JS CANVAS RENDERER (TILES WITH 0 CORNER ROUNDNESS)                   */
/* ========================================================================== */
/**
 * ============================================================================
 * WordleHelper - Canvas Renderer
 * ============================================================================
 * Handles p5.js drawing loops: animated 6x5 board grid with 3D flips,
 * interactive on-screen keyboard with disabled Enter key, and floating toasts.
 */

window.WordleApp = window.WordleApp || {};

WordleApp.Renderer = {
  /**
   * Draws the 6x5 tile grid, handling letter typography and flip animations.
   *
   * @param {Object} layout - Computed layout metrics.
   * @param {Array<Array<Object>>} grid - 2D grid matrix of cell objects.
   */
  drawGrid(layout, grid) {
    const { ROWS, COLS } = WordleApp.Constants.GRID;
    const { COLORS, ANIMATION } = WordleApp.Constants;
    const { tileSize, tileGap } = layout;

    const startX = (width - (COLS * tileSize + (COLS - 1) * tileGap)) / 2;
    const startY = layout.gridStartY;

    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        const x = startX + c * (tileSize + tileGap);
        const y = startY + r * (tileSize + tileGap);
        const cell = grid[r][c];
        let state = cell.state;
        let flipScale = 1;

        // Process vertical flip animation if active on this cell
        if (cell.flip) {
          const progress = Math.min(1, (millis() - cell.flip.startedAt) / ANIMATION.FLIP_DURATION_MS);
          flipScale = Math.max(0.04, Math.abs(Math.cos(progress * Math.PI)));
          // Color changes halfway through the flip
          state = progress < 0.5 ? cell.flip.from : cell.flip.to;

          if (progress >= 1) {
            cell.flip = null;
            flipScale = 1;
            state = cell.state;
          }
        }

        push();
        translate(x + tileSize / 2, y + tileSize / 2);
        scale(1, flipScale);

        // Cell background & border coloration based on evaluation state
        if (state === "correct") {
          fill(COLORS.correct);
          stroke(COLORS.correct);
        } else if (state === "present") {
          fill(COLORS.present);
          stroke(COLORS.present);
        } else if (state === "absent") {
          fill(COLORS.absent);
          stroke(COLORS.absent);
        } else {
          // Empty / blank tile state
          fill(COLORS.tileBg);
          stroke(cell.letter ? COLORS.tileBorderActive : COLORS.tileBorderEmpty);
        }

        strokeWeight(2);
        rect(-tileSize / 2, -tileSize / 2, tileSize, tileSize, 0);

        // Cell letter text
        if (cell.letter) {
          noStroke();
          // Use emptyTileText (dark text) for blank tiles in light mode
          fill(state === "empty" ? (COLORS.emptyTileText || COLORS.text) : COLORS.text);
          textSize(Math.round(tileSize * 0.52));
          textStyle(BOLD);
          text(cell.letter, 0, 1.5);
        }

        pop();
      }
    }
  },

  /**
   * Draws the on-screen keyboard, renders disabled Enter key, and collects hitboxes.
   *
   * @param {Object} layout - Computed layout metrics.
   * @param {Object} keyStates - Revealed feedback state for each key.
   * @param {Set<string>} possibleLetters - Set of letters mathematically allowed.
   * @param {Array<Object>} keyButtons - Output array storing button hitboxes for click detection.
   */
  drawKeyboard(layout, keyStates, possibleLetters, keyButtons) {
    const { KEYBOARD_ROWS, COLORS } = WordleApp.Constants;
    const { keyH, keyGap, baseKeyW, keyboardStartY } = layout;

    // Clear previous frame hitboxes
    keyButtons.length = 0;

    for (let r = 0; r < KEYBOARD_ROWS.length; r++) {
      const row = KEYBOARD_ROWS[r];
      let totalRowW = 0;

      for (let i = 0; i < row.length; i++) {
        const k = row[i];
        totalRowW += (k === "ENTER" || k === "BACK" ? baseKeyW * 1.5 : baseKeyW) + keyGap;
      }
      totalRowW -= keyGap;

      let currX = (width - totalRowW) / 2;
      const currY = keyboardStartY + r * (keyH + keyGap);

      for (let i = 0; i < row.length; i++) {
        const k = row[i];
        const keyW = k === "ENTER" || k === "BACK" ? baseKeyW * 1.5 : baseKeyW;
        const isEnter = k === "ENTER";
        const isUnavailable = /^[A-Z]$/.test(k) && !possibleLetters.has(k);
        const isDisabled = isEnter || isUnavailable;

        // Color key based on revealed state or disabled status
        const state = keyStates[k];
        if (isEnter) {
          fill(COLORS.keyEnterDisabledBg);
        } else if (isUnavailable) {
          fill(COLORS.keyUnavailableBg);
        } else if (state === "correct") {
          fill(COLORS.correct);
        } else if (state === "present") {
          fill(COLORS.present);
        } else if (state === "absent") {
          fill(COLORS.absent);
        } else {
          fill(COLORS.keyBg);
        }

        noStroke();
        rect(currX, currY, keyW, keyH, 4);

        // Key label text
        if (isEnter) {
          fill(COLORS.keyEnterDisabledText);
        } else if (isUnavailable) {
          fill(COLORS.keyUnavailableText);
        } else if (state === "correct" || state === "present" || state === "absent") {
          fill(COLORS.text);
        } else {
          fill(COLORS.keyText || COLORS.text);
        }

        const labelText = isEnter ? "ENTER" : (k === "BACK" ? "⌫" : k);
        textSize((k.length > 1 ? 10 : 13) * layout.scale);
        textStyle(BOLD);
        text(labelText, currX + keyW / 2, currY + keyH / 2);

        // Save hitbox for mouse/touch interactions
        keyButtons.push({
          key: k,
          x: currX,
          y: currY,
          w: keyW,
          h: keyH,
          disabled: isDisabled,
        });

        currX += keyW + keyGap;
      }
    }
  },

  /**
   * Draws the floating toast banner if active.
   *
   * @param {Object} layout - Computed layout metrics.
   * @param {string} message - Toast message text.
   * @param {number} messageTimer - Remaining frames for toast visibility.
   */
  drawToast(layout, message, messageTimer) {
    if (messageTimer <= 0 || !message) return;

    const { COLORS } = WordleApp.Constants;
    const scale = layout.scale;

    push();
    fill(COLORS.toastBg || [255, 255, 255]);
    stroke(COLORS.tileBorderEmpty || [80, 80, 80]);
    strokeWeight(1);
    rectMode(CENTER);

    textSize(13 * scale);
    textStyle(BOLD);
    const boxW = Math.max(160, textWidth(message) + 32 * scale);
    const boxH = 34 * scale;
    const toastY = Math.max(26 * scale, layout.gridStartY - 16);

    rect(width / 2, toastY, boxW, boxH, 6);

    noStroke();
    fill(COLORS.toastText || [0, 0, 0]);
    textAlign(CENTER, CENTER);
    text(message, width / 2, toastY);
    rectMode(CORNER);
    pop();
  },

  /**
   * Main render loop method called on every p5 draw tick.
   */
  render() {
    const { COLORS } = WordleApp.Constants;
    const state = WordleApp.State;
    const layout = WordleApp.Layout.getLayout(width, height);

    background(COLORS.bg);

    this.drawGrid(layout, state.grid);
    this.drawKeyboard(layout, state.keyStates, state.possibleLetters, state.keyButtons);
    this.drawToast(layout, state.message, state.messageTimer);

    // Decrement toast frame counter
    state.tickToast();
  },
};



/* ========================================================================== */
/* 10. INPUT & INTERACTION HANDLER                                            */
/* ========================================================================== */
/**
 * ============================================================================
 * WordleHelper - Input & Interaction Handler
 * ============================================================================
 * Manages physical and virtual keyboard input, continuous multi-row typing
 * without Enter key, tile color cycling (Green -> Absent/Blank -> Yellow -> Green), and candidate selection.
 */

window.WordleApp = window.WordleApp || {};

WordleApp.InputHandler = {
  /**
   * Processes a single input key command.
   *
   * @param {string} keyVal - Key identifier ("BACK", single letter A-Z, etc.).
   */
  handleInput(keyVal) {
    const state = WordleApp.State;
    const { ROWS, COLS } = WordleApp.Constants.GRID;

    // Enter key is explicitly disabled
    if (keyVal === "ENTER") {
      return;
    }

    // Handle Backspace / Delete (always allowed, even when row is filled with 5 green blocks or solved)
    if (keyVal === "BACK" || keyVal === "BACKSPACE") {
      state.gameOver = false;
      if (state.message && state.message.startsWith("Solved:")) {
        state.message = "";
        state.messageTimer = 0;
      }

      if (state.currentCol > 0) {
        state.currentCol--;
        state.grid[state.currentRow][state.currentCol].letter = "";
        state.grid[state.currentRow][state.currentCol].state = "empty";
        state.grid[state.currentRow][state.currentCol].flip = null;
        WordleApp.Solver.refreshLiveCandidates();
      } else if (state.currentRow > 0) {
        this.activateRow(state.currentRow - 1);
        state.currentCol = COLS;
        // Delete the last letter of the activated row on backspace
        if (state.currentCol > 0) {
          state.currentCol--;
          state.grid[state.currentRow][state.currentCol].letter = "";
          state.grid[state.currentRow][state.currentCol].state = "empty";
          state.grid[state.currentRow][state.currentCol].flip = null;
        }
        WordleApp.Solver.refreshLiveCandidates();
      }
      return;
    }

    if (state.gameOver) return;

    // Handle Alphabetical Letters (A-Z)
    if (/^[A-Z]$/.test(keyVal)) {
      // Case 1: Current row is full, but user continues typing for the next row
      if (state.currentCol === COLS) {
        if (state.currentRow < ROWS - 1 && state.liveWords.length > 1) {
          if (!state.possibleLetters.has(keyVal)) return;

          // Commit current row's feedback into confirmed state
          this.commitRow(state.currentRow);

          // Advance to next row
          state.currentRow++;
          state.currentCol = 0;

          // Place initial letter in Green
          state.grid[state.currentRow][0].letter = keyVal;
          state.grid[state.currentRow][0].state = "correct";
          state.grid[state.currentRow][0].flip = null;
          state.currentCol = 1;

          WordleApp.Solver.refreshLiveCandidates();
        } else if (state.liveWords.length === 1) {
          state.showToast(`Solved: ${state.liveWords[0]}`);
          state.gameOver = true;
        }
        return;
      }

      // Case 2: Typing within current row
      if (state.currentCol < COLS) {
        if (!state.possibleLetters.has(keyVal)) return;

        // Default fill block with Green (correct)
        state.grid[state.currentRow][state.currentCol].letter = keyVal;
        state.grid[state.currentRow][state.currentCol].state = "correct";
        state.grid[state.currentRow][state.currentCol].flip = null;
        state.currentCol++;

        WordleApp.Solver.refreshLiveCandidates();

        // Check if only 1 candidate left after completing word
        if (state.currentCol === COLS) {
          if (state.liveWords.length === 1) {
            state.showToast(`Solved: ${state.liveWords[0]}`);
            state.gameOver = true;
          } else if (state.liveWords.length === 0) {
            state.showToast("No matches. Check tile colors");
          }
        }
      }
    }
  },

  /**
   * Commits a completed row into confirmed solver constraints and updates key colors.
   *
   * @param {number} rowIndex - Row index to lock.
   */
  commitRow(rowIndex) {
    const state = WordleApp.State;
    const { COLS } = WordleApp.Constants.GRID;
    const row = state.grid[rowIndex];
    const priority = WordleApp.Constants.STATE_PRIORITY;

    // Update remainingWords to current liveWords
    state.remainingWords = [...state.liveWords];

    // Update keyboard key colors
    for (let c = 0; c < COLS; c++) {
      const cell = row[c];
      if (cell.letter && cell.state !== "empty") {
        if (
          state.keyStates[cell.letter] === undefined ||
          priority[cell.state] > priority[state.keyStates[cell.letter]]
        ) {
          state.keyStates[cell.letter] = cell.state;
        }
      }
    }
  },

  /**
   * Validates whether a row has all 5 letters filled.
   *
   * @param {Array<Object>} row - Row of cells.
   * @returns {boolean} True if all columns contain letters.
   */
  isRowComplete(row) {
    return row.every((cell) => Boolean(cell.letter));
  },

  /**
   * Activates a previous row for editing and resets rows below it.
   *
   * @param {number} rowIndex - Index of row to activate.
   */
  activateRow(rowIndex) {
    const state = WordleApp.State;
    const { ROWS, COLS } = WordleApp.Constants.GRID;

    if (rowIndex < 0 || rowIndex >= ROWS) return;

    state.currentRow = rowIndex;
    state.currentCol = state.grid[rowIndex].findIndex((cell) => !cell.letter);
    if (state.currentCol === -1) {
      state.currentCol = COLS;
    }
    state.gameOver = false;

    // Reset subsequent rows below activated row
    for (let r = rowIndex + 1; r < ROWS; r++) {
      state.grid[r] = Array.from({ length: COLS }, () => ({
        letter: "",
        state: "empty",
        flip: null,
      }));
    }

    WordleApp.Solver.rebuildRemainingWords();
  },

  /**
   * Populates the current row with a candidate word from the suggestions list.
   *
   * @param {string} word - 5-letter candidate word.
   */
  selectCandidate(word) {
    const state = WordleApp.State;
    const { ROWS, COLS } = WordleApp.Constants.GRID;

    if (state.gameOver) return;

    // If current row already has 5 letters and candidates remain, advance row first
    if (state.currentCol === COLS && state.currentRow < ROWS - 1 && state.liveWords.length > 1) {
      this.commitRow(state.currentRow);
      state.currentRow++;
      state.currentCol = 0;
    }

    if (state.currentRow >= ROWS) return;

    // Fill row with letters and default to Green
    state.grid[state.currentRow] = word.split("").map((letter) => ({
      letter,
      state: "correct",
      flip: null,
    }));
    state.currentCol = COLS;

    WordleApp.Solver.refreshLiveCandidates();

    if (state.liveWords.length === 1) {
      state.showToast(`Solved: ${state.liveWords[0]}`);
      state.gameOver = true;
    }
  },

  /**
   * Handles canvas click interactions (tile cycling, keyboard presses).
   *
   * @param {number} mouseX - Mouse X on canvas.
   * @param {number} mouseY - Mouse Y on canvas.
   */
  handleCanvasClick(mouseX, mouseY) {
    const state = WordleApp.State;
    const layout = WordleApp.Layout.getLayout(width, height);
    const { ROWS, COLS } = WordleApp.Constants.GRID;
    const { tileSize, tileGap } = layout;

    const startX = (width - (COLS * tileSize + (COLS - 1) * tileGap)) / 2;
    const startY = layout.gridStartY;

    // 1. Check if a board tile was clicked (cycle color including blank)
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        const x = startX + c * (tileSize + tileGap);
        const y = startY + r * (tileSize + tileGap);

        if (
          mouseX >= x &&
          mouseX <= x + tileSize &&
          mouseY >= y &&
          mouseY <= y + tileSize
        ) {
          if (r > state.currentRow) return;

          // Allow switching active row by clicking on it
          if (r !== state.currentRow) {
            this.activateRow(r);
          }

          const cell = state.grid[r][c];
          if (!cell.letter) return;

          // Reset gameOver and solved notification when user cycles tile feedback
          state.gameOver = false;
          if (state.message && state.message.startsWith("Solved:")) {
            state.message = "";
            state.messageTimer = 0;
          }

          // Cycle tile states: correct (green) -> absent (blank/gray) -> present (yellow) -> correct (green)
          const states = WordleApp.Constants.TILE_STATES;
          let currIdx = states.indexOf(cell.state);
          const nextState = currIdx === -1 ? states[0] : states[(currIdx + 1) % states.length];

          cell.flip = {
            from: cell.state,
            to: nextState,
            startedAt: millis(),
          };
          cell.state = nextState;

          WordleApp.Solver.refreshLiveCandidates();
          return;
        }
      }
    }

    // 2. Check if an on-screen keyboard button was clicked
    for (let i = 0; i < state.keyButtons.length; i++) {
      const btn = state.keyButtons[i];
      if (
        mouseX >= btn.x &&
        mouseX <= btn.x + btn.w &&
        mouseY >= btn.y &&
        mouseY <= btn.y + btn.h
      ) {
        // Disabled keys (like ENTER or unavailable letters) do nothing
        if (btn.disabled) return;
        // When game is over/solved, only allow the BACK button so user can back
        if (state.gameOver && btn.key !== "BACK") return;
        this.handleInput(btn.key);
        return;
      }
    }
  },

  /**
   * Handles physical keyboard key presses.
   *
   * @param {string} key - Pressed key string.
   * @param {number} keyCode - Numeric key code.
   * @returns {boolean} Returns false to prevent browser default scrolling.
   */
  handlePhysicalKey(key, keyCode) {
    if (key === "Enter" || keyCode === 13) {
      // Enter key is explicitly disabled
      return false;
    }

    if (key === "Backspace" || keyCode === 8) {
      this.handleInput("BACK");
      return false;
    }

    if (key.length === 1 && /^[a-zA-Z]$/.test(key)) {
      this.handleInput(key.toUpperCase());
    }
  },
};



/* ========================================================================== */
/* 11. APPLICATION BOOTSTRAP & P5 LIFECYCLE HOOKS                             */
/* ========================================================================== */
/**
 * ============================================================================
 * WordleHelper - Application Entry Point & p5.js Lifecycle Coordinator
 * ============================================================================
 * Orchestrates application bootstrap, responsive canvas resizing, p5 event loops,
 * theme setup, and global p5 lifecycle hook bindings.
 */

window.WordleApp = window.WordleApp || {};

WordleApp.Main = {
  APP_BAR_HEIGHT: 50,

  /**
   * Initializes theme, canvas, state, and DOM event handlers.
   */
  init() {
    const canvasW = Math.min(windowWidth, 800);
    const canvasH = Math.max(320, windowHeight - this.APP_BAR_HEIGHT);

    // 1. Create responsive p5 canvas and attach to DOM container #game
    createCanvas(canvasW, canvasH).parent("game");
    rectMode(CORNER);
    textAlign(CENTER, CENTER);

    // 2. Initialize Theme System
    if (WordleApp.ThemeManager) {
      WordleApp.ThemeManager.init();
    }

    // 3. Initialize DOM event listeners
    if (WordleApp.DOMManager) {
      WordleApp.DOMManager.init();
    }

    // 4. Initialize state with master word dictionary
    const initialWords = typeof WORD_LIST !== "undefined" ? WORD_LIST : [];
    WordleApp.State.init(initialWords);

    // 5. Initial filter run to show full candidate list
    WordleApp.Solver.refreshLiveCandidates();
  },

  /**
   * Main animation loop invoked on every frame tick by p5.js.
   */
  render() {
    WordleApp.Renderer.render();
  },

  /**
   * Handles browser viewport resize events to dynamically adjust canvas dimensions.
   */
  handleResize() {
    const canvasW = Math.min(windowWidth, 800);
    const canvasH = Math.max(320, windowHeight - this.APP_BAR_HEIGHT);
    resizeCanvas(canvasW, canvasH);
  },

  /**
   * Resets the entire solver state.
   */
  reset() {
    WordleApp.State.reset();
  },
};

/* -------------------------------------------------------------------------- */
/* Global p5.js Lifecycle Hook Bindings                                       */
/* -------------------------------------------------------------------------- */

/**
 * Global p5 setup callback.
 */
function setup() {
  WordleApp.Main.init();
}

/**
 * Global p5 draw callback.
 */
function draw() {
  WordleApp.Main.render();
}

/**
 * Global p5 resize callback.
 */
function windowResized() {
  WordleApp.Main.handleResize();
}

/**
 * Global p5 physical keyboard callback.
 */
function keyPressed() {
  if (WordleApp.DOMManager && WordleApp.DOMManager.isListPageOpen()) {
    if (keyCode === ESCAPE || key === "Escape") {
      WordleApp.DOMManager.hideListPage();
      return false;
    }
    return true;
  }
  return WordleApp.InputHandler.handlePhysicalKey(key, keyCode);
}

/**
 * Global p5 mouse/touch click callback.
 */
function mousePressed() {
  if (WordleApp.DOMManager && WordleApp.DOMManager.isListPageOpen()) {
    return;
  }
  WordleApp.InputHandler.handleCanvasClick(mouseX, mouseY);
}




// Asynchronously reload words from WordList.txt if served via HTTP server and available
if (typeof window !== "undefined" && window.location && window.location.protocol.startsWith("http")) {
  fetch("WordList.txt")
    .then((res) => (res.ok ? res.text() : null))
    .then((text) => {
      if (text) {
        const words = text
          .split(/\r?\n/)
          .map((w) => w.trim().toUpperCase())
          .filter((w) => w.length === 5);
        if (words.length > 0) {
          window.WORD_LIST = words;
          if (window.WordleApp && window.WordleApp.State) {
            window.WordleApp.State.remainingWords = [...words];
            if (window.WordleApp.Solver) {
              window.WordleApp.Solver.refreshLiveCandidates();
            }
          }
        }
      }
    })
    .catch(() => {
      // Graceful fallback to embedded WORD_LIST
    });
}
